'use client';

import { IconLanguage, IconSelector } from '@tabler/icons-react';
import { useLocale, useTranslations } from 'next-intl';
import { useTransition } from 'react';

import { LanguageSwitcherItems, LanguageSwitcherMenu } from '@/components/language-switcher-menu';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { SidebarMenuButton, SidebarMenuItem, useSidebar } from '@/components/ui/sidebar';
import { Spinner } from '@/components/ui/spinner';
import { setLocale } from '@/i18n/actions';
import { type Locale, locales } from '@/i18n/config';

// Expects the app's `src/i18n/config.ts` (locales, Locale) and `src/i18n/actions.ts`
// (`setLocale` server action that writes the locale cookie).

function useLocaleMenu() {
  const t = useTranslations('ui');
  const locale = useLocale();
  const [pending, startTransition] = useTransition();

  const choose = (next: Locale) => {
    if (next !== locale) startTransition(() => setLocale(next));
  };

  const options = locales.map((option) => ({
    locale: option,
    label: t(`languages.${option}`),
    onChoose: () => choose(option),
  }));

  return { t, locale, pending, options };
}

/** Header variant: the globe button. */
export function LocaleSwitcher() {
  const { t, locale, pending, options } = useLocaleMenu();

  return (
    <LanguageSwitcherMenu
      locale={locale}
      label={t('language')}
      pending={pending}
      options={options}
    />
  );
}

/** Sidebar variant: a menu item with the current language. */
export function SidebarLocaleSwitcher() {
  const { t, locale, pending, options } = useLocaleMenu();
  const { isMobile } = useSidebar();

  return (
    <SidebarMenuItem>
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <SidebarMenuButton
              tooltip={t('language')}
              aria-label={t('language')}
              disabled={pending}
              aria-busy={pending}
            />
          }
        >
          {pending ? <Spinner /> : <IconLanguage />}
          <span className="flex-1 truncate">{t(`languages.${locale}`)}</span>
          <IconSelector className="ml-auto group-data-[collapsible=icon]:hidden" />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          side={isMobile ? 'bottom' : 'right'}
          align="end"
          sideOffset={8}
          className="min-w-40"
        >
          <LanguageSwitcherItems locale={locale} options={options} pending={pending} />
        </DropdownMenuContent>
      </DropdownMenu>
    </SidebarMenuItem>
  );
}

'use client';

import { IconCheck, IconSelector, IconWorld } from '@tabler/icons-react';
import Link from 'next/link';

import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Spinner } from '@/components/ui/spinner';
import { cn } from '@/lib/utils';

export type LanguageOption = {
  locale: string;
  label: string;
} & ({ href: string; onChoose?: never } | { href?: never; onChoose: () => void });

export type LanguageSwitcherMenuProps = {
  locale: string;
  label: string;
  options: LanguageOption[];
  pending?: boolean;
  className?: string;
};

export function LanguageSwitcherItems({
  locale,
  options,
  pending = false,
}: Pick<LanguageSwitcherMenuProps, 'locale' | 'options' | 'pending'>) {
  return options.map((option) => (
    <DropdownMenuItem
      key={option.locale}
      lang={option.locale}
      render={
        option.href !== undefined ? (
          <Link href={option.href} hrefLang={option.locale} lang={option.locale} />
        ) : undefined
      }
      onClick={option.onChoose}
      disabled={pending}
      aria-current={option.locale === locale ? 'true' : undefined}
    >
      <span className="w-6 text-xs font-semibold text-muted-foreground uppercase">
        {option.locale}
      </span>
      <span className="flex-1">{option.label}</span>
      {option.locale === locale && <IconCheck className="ml-auto" />}
    </DropdownMenuItem>
  ));
}

/** Globe button that opens the language list; items are links (public pages) or callbacks. */
export function LanguageSwitcherMenu({
  locale,
  label,
  options,
  pending = false,
  className,
}: LanguageSwitcherMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant="outline"
            size="sm"
            className={cn('shrink-0 text-foreground', className)}
            aria-label={label}
            disabled={pending}
            aria-busy={pending}
          />
        }
      >
        {pending ? <Spinner /> : <IconWorld className="text-primary" />}
        <span className="uppercase">{locale}</span>
        <IconSelector />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" sideOffset={8} className="min-w-40">
        <LanguageSwitcherItems locale={locale} options={options} pending={pending} />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { useEffect } from 'react';

/** Sets `<html lang>` for a subtree whose language differs from the root layout's. */
export function DocumentLang({ lang }: { lang: string }) {
  useEffect(() => {
    const html = document.documentElement;
    const previous = html.lang;
    html.lang = lang;
    return () => {
      html.lang = previous;
    };
  }, [lang]);

  return null;
}
